capture_round_tracked_paths() {
    {
        git diff --name-only 2>/dev/null || true
        git diff --name-only --cached 2>/dev/null || true
    } | awk 'NF && !seen[$0]++ { print }'
}

input.new_string:
capture_round_tracked_paths() {
    {
        git diff --name-only 2>/dev/null || true
        git diff --name-only --cached 2>/dev/null || true
    } | awk 'NF && !seen[$0]++ { print }'
}

capture_round_untracked_paths() {
    git status --porcelain 2>/dev/null \
        | awk '$1 == "??" { sub(/^\?\?[[:space:]]*/, ""); print }'
}

